'use client';

import { useState, useEffect } from 'react';
import { api } from '@/lib/api';
import { FileCheck, Download, BarChart3 } from 'lucide-react';

export default function CompliancePage() {
    const [summary, setSummary] = useState<any>(null);
    const [loading, setLoading] = useState(false);

    const loadSummary = async () => {
        setLoading(true);
        try {
            const res = await api.get<any>('/api/compliance/semester-summary');
            if (res.success) setSummary(res.data);
        } catch (e) { }
        setLoading(false);
    };

    const downloadCSV = async () => {
        try {
            await api.download('/api/compliance/export/csv', 'edunexis_compliance_report.csv');
        } catch (e) { }
    };

    const downloadPDF = async () => {
        try {
            await api.download('/api/compliance/export/pdf', 'edunexis_compliance_report.pdf');
        } catch (e) { }
    };

    return (
        <div>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 24 }}>
                <div>
                    <h1 style={{ fontSize: 24, fontWeight: 700, color: '#142B34', fontFamily: 'Poppins' }}>Compliance Reports</h1>
                    <p style={{ fontSize: 14, color: '#5a6a72' }}>Generate academic summaries and regulatory exports</p>
                </div>
                <div style={{ display: 'flex', gap: 8 }}>
                    <button className="btn-primary" onClick={loadSummary} disabled={loading}>
                        <BarChart3 size={16} /> {loading ? 'Loading...' : 'Generate Summary'}
                    </button>
                    <button className="btn-secondary btn-sm" onClick={downloadCSV}>
                        <Download size={14} /> CSV
                    </button>
                    <button className="btn-secondary btn-sm" onClick={downloadPDF}>
                        <Download size={14} /> PDF
                    </button>
                </div>
            </div>

            {summary ? (
                <>
                    {/* Key Metrics */}
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 16, marginBottom: 24 }}>
                        {[
                            { label: 'Total Students', value: summary.student_count, color: '#2563eb' },
                            { label: 'Total Faculty', value: summary.faculty_count, color: '#059669' },
                            { label: 'Pass %', value: `${summary.pass_percentage}%`, color: '#7c3aed' },
                            { label: 'Attendance Avg', value: `${summary.attendance_average}%`, color: '#d97706' },
                        ].map((m, i) => (
                            <div key={i} className="card" style={{ padding: 24 }}>
                                <div style={{ fontSize: 13, color: '#8a9aa2', marginBottom: 8 }}>{m.label}</div>
                                <div style={{ fontSize: 28, fontWeight: 800, color: m.color, fontFamily: 'Poppins' }}>{m.value}</div>
                            </div>
                        ))}
                    </div>

                    {/* Student-Faculty Ratio */}
                    <div className="card" style={{ marginBottom: 24, padding: 24 }}>
                        <h3 style={{ fontSize: 16, fontWeight: 700, marginBottom: 12 }}>Student-Faculty Ratio</h3>
                        <div style={{ fontSize: 24, fontWeight: 700, color: '#142B34' }}>
                            {summary.student_faculty_ratio}:1
                        </div>
                    </div>

                    {/* Subject Performance */}
                    {summary.subject_performance && summary.subject_performance.length > 0 && (
                        <div className="card" style={{ padding: 24 }}>
                            <h3 style={{ fontSize: 16, fontWeight: 700, marginBottom: 16 }}>Subject Performance</h3>
                            <div className="table-container">
                                <table>
                                    <thead><tr><th>Subject ID</th><th>Students</th><th>Avg Marks</th><th>Max</th></tr></thead>
                                    <tbody>
                                        {summary.subject_performance.map((s: any, i: number) => (
                                            <tr key={i}>
                                                <td style={{ fontWeight: 600 }}>{s.subject_id}</td>
                                                <td>{s.student_count}</td>
                                                <td style={{ fontWeight: 700 }}>{s.average_marks}</td>
                                                <td>{s.max_marks}</td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    )}
                </>
            ) : (
                <div className="card" style={{ textAlign: 'center', padding: 48, color: '#8a9aa2' }}>
                    <FileCheck size={40} style={{ margin: '0 auto 12px', opacity: 0.3 }} />
                    <p>Click "Generate Summary" to view academic compliance data</p>
                </div>
            )}
        </div>
    );
}
